#!/usr/bin/env bash
#
# frontend_v1.catalog — the bundle's copy of the A2UI v1.0 finance catalog.
#
# The renderer enforces the catalog's composition rules (ADR-M D-4) and
# advertises its `catalogId` on every request (D-8), so the app ships a copy
# of it as an asset: app/assets/a2ui/finance.catalog.json. The catalog itself
# is GENERATED by the backend from the projection registry (D-5,
# `cd backend && make catalog` → docs/a2ui/v1.0/finance.catalog.json).
#
# Until that file exists, the source is the provisional fixture the a2ui_v1
# suite reads, which encodes ADR-M D-4 by hand. The day the generated file
# lands, this script switches to it on its own — no edit here — and
# `--check` turns red until someone runs `make catalog` and commits the copy.
# A generated artefact is gated by regeneration, never by trust
# (.claude/rules/ci-conventions.md §4).
#
#   bash tool/sync_catalog.sh           # write the copy
#   bash tool/sync_catalog.sh --check   # fail if the copy is stale

set -Eeuo pipefail

cd "$(dirname "${BASH_SOURCE[0]}")/.."

GENERATED="../docs/a2ui/v1.0/finance.catalog.json"
PROVISIONAL="packages/a2ui_v1/test/fixtures/finance.catalog.provisional.json"
TARGET="app/assets/a2ui/finance.catalog.json"

if [ -f "$GENERATED" ]; then
  source_file="$GENERATED"
else
  source_file="$PROVISIONAL"
fi

if [ "${1:-}" = "--check" ]; then
  if ! cmp -s "$source_file" "$TARGET"; then
    echo "frontend_v1.catalog: ${TARGET} is not a copy of ${source_file}" >&2
    echo "  regenerate it and commit the result:  cd frontend_v1 && make catalog" >&2
    exit 1
  fi
  echo "frontend_v1.catalog: ${TARGET} matches ${source_file}"
  exit 0
fi

mkdir -p "$(dirname "$TARGET")"
cp "$source_file" "$TARGET"
echo "frontend_v1.catalog: wrote ${TARGET} from ${source_file}"
